def build_methods(reviewed_date: str | None = None) -> list[dict]:
    from .names_ar import NAMES_AR

    out = []
    by_cat_prefix = {"BANK": "banking", "MAIL": "phishing_email", "SMS": "sms_whatsapp", "GOV": "government", "DLV": "delivery", "JOB": "job",
                     "INV": "investment", "ROM": "romance", "ECOM": "ecommerce", "SUP": "support", "ID": "identity", "OTP": "otp_takeover",
                     "PAY": "payment_refund", "QR": "qr", "TECH": "tech_support", "DF": "deepfake", "BEC": "bec", "RENT": "rental",
                     "CHR": "charity", "EMG": "emerging"}
    ids = {r[0] for r in ROWS}
    for (mid, name, sub, desc, seq, inds, en, ar, sev, uae, variations) in ROWS:
        cat = by_cat_prefix[mid.split("-")[0]]
        c = CATEGORIES[cat]
        related = [x for x in sorted(ids) if x.split("-")[0] == mid.split("-")[0] and x != mid][:3]
        out.append({
            "id": f"SM-{mid}", "name": name, "name_ar": NAMES_AR.get(mid) or None, "category": cat, "category_name": c["name"], "subcategory": sub,
            "description": desc, "how_it_works": desc, "attack_sequence": [s.strip() for s in seq.split(">")],
            "psychological_techniques": c["psychology"], "attacker_objectives": c["objectives"], "typical_targets": c["targets"],
            "channels": c["channels"], "behavioral_indicators": [s.strip() for s in inds.split(";")] + c["detection"][:1],
            "technical_indicators": [], "examples": {"en": [en], "ar": [ar]}, "variations": [v.strip() for v in variations.split(";") if v.strip()],
            "detection_strategies": c["detection"], "protection_steps": c["protection"], "severity": sev,
            "impact": {"critical": "Direct loss of money or full account takeover", "high": "Likely financial loss or identity misuse",
                       "medium": "Possible loss; usually smaller amounts or data", "low": "Nuisance or small loss"}[sev],
            "related_methods": [f"SM-{x}" for x in related], "uae_focus": uae,
            "sources": [], "source_note": "Written by the 3B team from general fraud-awareness knowledge. Add a traceable source before verifying.",
            "examples_are_fictional": True, "review_status": "needs_review", "last_reviewed": reviewed_date,
        })
    return out
